on_atestado":"b43f940e3a7d8e518b5daa8a83dc70ad23a7d818ac5ffa3422b8d526d91396cd","hash_paquete_atestado":"1daf6afb444d3ac8e3064da89916e6a08482bba8a1350dad0143d24abf56b7ed","veredicto":"PASS","juez":"Claude independiente 2026-11-24 02:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.8,"observacion":"Allowlist exacta de orígenes pendiente; no se inventan dominios."},"CAL_ALCANCE":{"puntaje":0.9,"observacion":"Incluye orígenes, métodos y headers."},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":218,"familia":"SECURITY","diferencias":"Contraste funcional: BLOQUEAR CORS productivo wildcard o solicitud cross-origin desde origen no autorizado; restringir métodos y headers al contrato vigente, sin inventar dominios.","residual":"Allowlist exacta de orígenes producción/staging, métodos GET/POST/PATCH y headers Content-Type/Authorization/X-Idempotency-Key pendientes de contrato físico verificado."},{"codigo":"S9-C22","version":1,"eval_id":764,"hash_version_atestado":"e5d4e5eee53fa1306f4857f25ae43f882699892dba6df15ca2f8b634b8095e30","hash_paquete_atestado":"25b58ea880b48fb785558b3485cc4bdf57b2cc42b1f1dfb8b93373a23e1eea93","veredicto":"PASS","juez":"Claude independiente 2026-11-24 02:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Misma observación que S9-C01."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":221,"familia":"NOTIFICATIONS_DELIVERY","diferencias":"Contraste funcional: BLOQUEAR envío de notificación comercial sin consentimiento comercial; no exigirlo para OTP, confirmaciones ni alertas operativas. Complementa S9-C01 sobre campañas y r